#include <stdio.h>

int main(void)
{
    float x, y;

    printf("Введіть значення x: ");
    if (scanf("%f", &x) != 1)
    {
        printf("Помилка введення.\n");
        return 1;
    }

    if ((x > -10 && x <= -5) || (x > 5 && x <= 15))
    {
        y = x * x * x - 6;
        printf("y = %f\n", y);
    }
    else if (x >= 25)
    {
        y = 2 * x * x * x - 3 * x + 2;
        printf("y = %f\n", y);
    }
    else
    {
        printf("Функція не існує для x = %.2f\n", x);
        printf("Причина: ");

        if (x <= -10)
        {
            printf("значення x <= -10 (знаходиться лівіше від інтервалу (-10, -5]).\n");
        }
        else if (x > -5 && x <= 5)
        {
            printf("значення x потрапляє у проміжок (-5, 5] між допустимими інтервалами.\n");
        }
        else if (x > 15 && x < 25)
        {
            printf("значення x потрапляє у проміжок (15, 25) між допустимими інтервалами.\n");
        }
    }

    return 0;
}
